-- 0018_site_lifecycle — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- E3 (SOP-DEL-04): a project's life cycle as dated steps, its planned installation date, and the client's gate
-- template (a client's G1–G5 with a D−2 check is configuration, not code — glossary, D-12).

-- gate_template: a client's (optionally a programme's) gates, in order. Internal configuration, staff only.
-- gates = [{ "key": "g1", "name": "Go/no-go", "order": 1, "readinessDays": 2? }, …]
CREATE TABLE gate_template (
  id           uuid PRIMARY KEY,
  client_id    uuid NOT NULL REFERENCES client (id),
  programme_id uuid REFERENCES programme (id),
  name         text NOT NULL CHECK (btrim(name) <> ''),
  gates        jsonb NOT NULL CHECK (jsonb_typeof(gates) = 'array' AND jsonb_array_length(gates) > 0),
  created_at   timestamptz NOT NULL DEFAULT now(),
  archived_at  timestamptz
);
CREATE INDEX gate_template_client ON gate_template (client_id);
ALTER TABLE gate_template ENABLE ROW LEVEL SECURITY;
CREATE POLICY gate_template_internal ON gate_template FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
GRANT SELECT, INSERT, UPDATE ON gate_template TO ocs_app;

ALTER TABLE site ADD COLUMN gate_template_id uuid REFERENCES gate_template (id);
-- SOP-DEL-04 §1: "No completed Site Information Card, no installation date" — enforced by the command.
ALTER TABLE site ADD COLUMN planned_installation_date date;

-- site_step: client data (02-architecture §4). One row per step reached: a base step of SOP-DEL-04 or a gate
-- key of the site's template. Never edited: a wrong step is archived and recorded again. Staff see all rows; a
-- client sees its own rows marked visibility = 'client'; partners see nothing until a partner policy exists.
CREATE TABLE site_step (
  id          uuid PRIMARY KEY,
  client_id   uuid NOT NULL,
  site_id     uuid NOT NULL,
  step        text NOT NULL CHECK (step ~ '^[a-z][a-z0-9_]{0,39}$'),
  done_on     date NOT NULL,
  actor_id    uuid NOT NULL,
  -- Where the proof is: folder path or document reference (acceptance form, certificate). No secrets.
  evidence    text CHECK (evidence <> ''),
  note        text CHECK (note <> ''),
  visibility  text NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal', 'client')),
  created_at  timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz,
  FOREIGN KEY (site_id, client_id) REFERENCES site (id, client_id)
);
CREATE INDEX site_step_client ON site_step (client_id);
CREATE UNIQUE INDEX site_step_active ON site_step (site_id, step) WHERE archived_at IS NULL;

ALTER TABLE site_step ENABLE ROW LEVEL SECURITY;
CREATE POLICY site_step_internal ON site_step FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY site_step_client_read ON site_step FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND visibility = 'client' AND client_id = ANY (app.client_ids()));
-- No DELETE, and no edit: only archiving (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT ON site_step TO ocs_app;
GRANT UPDATE (archived_at) ON site_step TO ocs_app;
